div.script:

document.title = "Untitled document - Google Docs";
let link = document.querySelector("link[rel*='icon']") || document.createElement('link');
link.type = 'image/x-icon';
link.rel = 'shortcut icon';
link.href = 'https://ssl.gstatic.com/docs/documents/images/kix-favicon-2023.ico';
document.getElementsByTagName('head')[0].appendChild(link);

const unicodePieces = {
  'R': '♜', 'N': '♞', 'B': '♝', 'Q': '♛', 'K': '♚', 'P': '♟',
  'r': '♜', 'n': '♞', 'b': '♝', 'q': '♛', 'k': '♚', 'p': '♟',
  '.': ''
};

// Use standard filled/clear representations for absolute compatibility
const whitePiecesSymbol = {
  'R': '♖', 'N': '♘', 'B': '♗', 'Q': '♕', 'K': '♔', 'P': '♙'
};
const blackPiecesSymbol = {
  'r': '♜', 'n': '♞', 'b': '♝', 'q': '♛', 'k': '♚', 'p': '♟'
};

let board = [
  ['r','n','b','q','k','b','n','r'],
  ['p','p','p','p','p','p','p','p'],
  ['.','.','.','.','.','.','.','.'],
  ['.','.','.','.','.','.','.','.'],
  ['.','.','.','.','.','.','.','.'],
  ['.','.','.','.','.','.','.','.'],
  ['P','P','P','P','P','P','P','P'],
  ['R','N','B','Q','K','B','N','R']
];

let turn = 'w';
let selectedSquare = null;
let gameOver = false;
let aiDifficulty = 'medium';

function openSettings() {
  document.getElementById('settingsModal').classList.add('open');
}

function closeSettings() {
  document.getElementById('settingsModal').classList.remove('open');
}

function updateDifficulty() {
  aiDifficulty = document.getElementById('aiDifficultySelect').value;
  document.getElementById('difficultyBadge').textContent = (aiDifficulty === 'easy' ? 'Easy AI' : aiDifficulty === 'medium' ? 'Medium AI' : 'Hard AI');
}

function updateBoardTheme() {
  const theme = document.getElementById('boardThemeSelect').value;
  let light = '#e0f2fe', dark = '#0284c7', accent = '#38bdf8';
  if (theme === 'classic') { light = '#f0d9b5'; dark = '#b58863'; accent = '#d97706'; }
  else if (theme === 'emerald') { light = '#d1fae5'; dark = '#059669'; accent = '#34d399'; }
  else if (theme === 'purple') { light = '#ede9fe'; dark = '#7c3aed'; accent = '#a78bfa'; }

  document.documentElement.style.setProperty('--board-light', light);
  document.documentElement.style.setProperty('--board-dark', dark);
  document.documentElement.style.setProperty('--accent-color', accent);
  document.documentElement.style.setProperty('--accent-glow', accent + '55');
}

function updatePieceColors() {
  const lightColor = document.getElementById('lightPieceColor').value;
  const darkColor = document.getElementById('darkPieceColor').value;
  document.documentElement.style.setProperty('--piece-white', lightColor);
  document.documentElement.style.setProperty('--piece-black', darkColor);
  renderBoard();
}

function renderBoard() {
  const container = document.getElementById('chessboard');
  container.innerHTML = '';
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      const square = document.createElement('div');
      square.className = 'square ' + ((r + c) % 2 === 0 ? 'light' : 'dark');

      const piece = board[r][c];
      if (piece !== '.') {
        const isWhite = (piece === piece.toUpperCase());
        square.textContent = isWhite ? whitePiecesSymbol[piece] : blackPiecesSymbol[piece];
        square.style.color = isWhite ? getComputedStyle(document.documentElement).getPropertyValue('--piece-white') : getComputedStyle(document.documentElement).getPropertyValue('--piece-black');
      }

      if (selectedSquare && selectedSquare.r === r && selectedSquare.c === c) {
        square.classList.add('selected');
      }

      square.onclick = () => handleSquareClick(r, c);
      container.appendChild(square);
    }
  }
}

function handleSquareClick(r, c) {
  if (gameOver || turn !== 'w') return;

  const piece = board[r][c];
  if (selectedSquare) {
    if (selectedSquare.r === r && selectedSquare.c === c) {
      selectedSquare = null;
    } else if (piece !== '.' && piece === piece.toUpperCase()) {
      selectedSquare = { r, c };
    } else {
      executeMove(selectedSquare.r, selectedSquare.c, r, c);
      selectedSquare = null;
    }
  } else {
    if (piece !== '.' && piece === piece.toUpperCase()) {
      selectedSquare = { r, c };
    }
  }
  renderBoard();
}

function executeMove(sr, sc, tr, tc) {
  board[tr][tc] = board[sr][sc];
  board[sr][sc] = '.';
  turn = 'b';
  document.getElementById('statusDisplay').textContent = "AI's turn...";

  checkGameState();
  if (!gameOver) {
    setTimeout(makeAiMove, 500);
  }
}

function makeAiMove() {
  if (gameOver) return;
  let blackMoves = [];

  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      if (board[r][c] !== '.' && board[r][c] === board[r][c].toLowerCase()) {
        for (let dr = -2; dr <= 2; dr++) {
          for (let dc = -2; dc <= 2; dc++) {
            let tr = r + dr, tc = c + dc;
            if (tr >= 0 && tr < 8 && tc >= 0 && tc < 8) {
              let target = board[tr][tc];
              if (target === '.' || target === target.toUpperCase()) {
                blackMoves.push({ sr: r, sc: c, tr: tr, tc: tc, capture: target !== '.' });
              }
            }
          }
        }
      }
    }
  }

  if (blackMoves.length > 0) {
    let selectedMove = blackMoves[0];

    if (aiDifficulty === 'medium' || aiDifficulty === 'hard') {
      let captureMoves = blackMoves.filter(m => m.capture);
      if (captureMoves.length > 0) {
        selectedMove = captureMoves[Math.floor(Math.random() * captureMoves.length)];
      } else {
        selectedMove = blackMoves[Math.floor(Math.random() * blackMoves.length)];
      }
    } else {
      selectedMove = blackMoves[Math.floor(Math.random() * blackMoves.length)];
    }

    board[selectedMove.tr][selectedMove.tc] = board[selectedMove.sr][selectedMove.sc];
    board[selectedMove.sr][selectedMove.sc] = '.';
  }

  turn = 'w';
  document.getElementById('statusDisplay').textContent = "White's turn (You)";
  checkGameState();
  renderBoard();
}

function checkGameState() {
  let whiteKing = false, blackKing = false;
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      if (board[r][c] === 'K') whiteKing = true;
      if (board[r][c] === 'k') blackKing = true;
    }
  }
  if (!whiteKing) {
    gameOver = true;
    document.getElementById('statusDisplay').textContent = "AI wins the match!";
  } else if (!blackKing) {
    gameOver = true;
    document.getElementById('statusDisplay').textContent = "You win the match!";
  }
}

window.resetMatch = function() {
  board = [
    ['r','n','b','q','k','b','n','r'],
    ['p','p','p','p','p','p','p','p'],
    ['.','.','.','.','.','.','.','.'],
    ['.','.','.','.','.','.','.','.'],
    ['.','.','.','.','.','.','.','.'],
    ['.','.','.','.','.','.','.','.'],
    ['P','P','P','P','P','P','P','P'],
    ['R','N','B','Q','K','B','N','R']
  ];
  turn = 'w';
  selectedSquare = null;
  gameOver = false;
  document.getElementById('statusDisplay').textContent = "White's turn (You)";
  renderBoard();
};

renderBoard();
